<?php require __DIR__.'/bootstrap.php'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $n=trim($_POST['name']??'');$em=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';$plan=$_POST['plan']??'basic'; if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)$err='Informe nome, e-mail válido e senha com 10 caracteres.';else try{$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"member")')->execute([$n,$em,password_hash($pw,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$p=$pdo->prepare('SELECT id FROM plans WHERE code=?');$p->execute([$plan]);$pid=$p->fetchColumn();$pdo->prepare('INSERT INTO subscriptions(user_id,plan_id,status,trial_ends_at) VALUES(?, ?, "trial", DATE_ADD(NOW(),INTERVAL 7 DAY))')->execute([$uid,$pid]);$_SESSION['arena_user']=$uid;header('Location: conta.php');exit;}catch(Throwable $e){$err='Este e-mail já possui cadastro.';}} ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Criar conta — Arena de Aço</title><link rel="stylesheet" href="assets/app.css"></head><body class="auth"><main class="authbox"><a class="brand" href="index.php">⚔ ARENA DE AÇO</a><p class="kicker">7 DIAS GRÁTIS</p><h1>Crie sua conta.</h1><?php if($err):?><p class="alert err"><?=e($err)?></p><?php endif?><form method="post"><label>Nome<input required name="name"></label><label>E-mail<input required type="email" name="email"></label><label>Senha<input required minlength="10" type="password" name="password"></label><label>Plano<select name="plan"><option value="basic">Básico — R$ 9,90</option><option value="premium">Premium — R$ 19,90</option><option value="ultimate">Ultimate — R$ 29,90</option></select></label><button class="btn full">Começar período grátis →</button></form><p>Já possui conta? <a href="login.php">Entrar</a></p></main></body></html>
